150	    };
151	    const dev_disp_s1_config_t *dev_config = (config != NULL) ? config : &s_default_config;
152	    uint16_t dummy_reg = 0U;
153	    esp_err_t ret;
154	
155	    if (s_dev_disp_s1.is_initialized) {
156	        return ESP_OK;
157	    }
158	
159	    ret = hal_i2c_get_ops()->bus_init(&i2c_config, &s_dev_disp_s1.bus_handle);
160	    if (ret != ESP_OK) {
161	        ESP_LOGE(TAG, "I2C bus init failed: %s", esp_err_to_name(ret));
162	        return ret;
163	    }
164	
165	    ret = dev_disp_s1_enable_external_hw();
166	    if (ret != ESP_OK) {
167	        return ret;
168	    }
169	
170	    ret = hal_i2c_get_ops()->device_add(s_dev_disp_s1.bus_handle,
171	                                        dev_config->i2c_addr,
172	                                        DEV_DISP_S1_I2C_SPEED_HZ,
173	                                        &s_dev_disp_s1.dev_handle);
174	    if (ret != ESP_OK) {
175	        ESP_LOGE(TAG, "I2C device add failed: %s", esp_err_to_name(ret));
176	        return ret;
177	    }
178	
179	    ret = dev_disp_s1_read_reg(ADS1115_REG_CONFIG, &dummy_reg);
180	    if (ret != ESP_OK) {
181	        ESP_LOGE(TAG, "ADS1115 communication check failed: %s", esp_err_to_name(ret));
182	        hal_i2c_get_ops()->device_remove(s_dev_disp_s1.dev_handle);
183	        s_dev_disp_s1.dev_handle = NULL;
184	        return ret;
185	    }
186	
187	    s_dev_disp_s1.config = *dev_config;
188	    s_dev_disp_s1.zero_raw = 0;
189	    s_dev_disp_s1.has_zero = false;
190	    s_dev_disp_s1.is_initialized = true;
191	    s_dev_disp_s1.is_online = true;
192	    ESP_LOGI(TAG, "init ok: addr=0x%02X scale=%.6f mm/lsb offset=%.3f mm",
193	             s_dev_disp_s1.config.i2c_addr,
194	             s_dev_disp_s1.config.scale_mm_per_lsb,
