214	esp_err_t dev_disp_s1_read(dev_disp_s1_data_t *out)
215	{
216	    uint16_t raw_reg = 0U;
217	    int16_t raw_value;
218	    float voltage_v;
219	    float absolute_mm;
220	
221	    if (out == NULL) {
222	        return ESP_ERR_INVALID_ARG;
223	    }
224	
225	    if (!s_dev_disp_s1.is_initialized) {
226	        ESP_LOGE(TAG, "device not initialized");
227	        return ESP_ERR_INVALID_STATE;
228	    }
229	
230	    if (dev_disp_s1_write_reg(ADS1115_REG_CONFIG,
231	                              (uint16_t)(ADS1115_OS_START |
232	                                         ADS1115_MUX_AI0_GND |
233	                                         ADS1115_PGA_6_144V |
234	                                         ADS1115_DR_128SPS |
235	                                         ADS1115_MODE_SINGLE)) != ESP_OK) {
236	        s_dev_disp_s1.is_online = false;
237	        ESP_LOGE(TAG, "start conversion failed");
238	        return ESP_FAIL;
239	    }
240	
241	    vTaskDelay(pdMS_TO_TICKS(DEV_DISP_S1_CONVERSION_WAIT_MS));
242	
243	    if (dev_disp_s1_read_reg(ADS1115_REG_CONV, &raw_reg) != ESP_OK) {
244	        s_dev_disp_s1.is_online = false;
245	        ESP_LOGE(TAG, "read conversion failed");
246	        return ESP_FAIL;
247	    }
248	
249	    raw_value = (int16_t)raw_reg;
250	    voltage_v = dev_disp_s1_raw_to_voltage(raw_value);
251	    absolute_mm = dev_disp_s1_raw_to_mm(raw_value);
252	
253	    out->raw_value = raw_value;
254	    out->voltage_v = voltage_v;
255	    out->disp_mm = s_dev_disp_s1.has_zero
256	        ? (absolute_mm - dev_disp_s1_raw_to_mm(s_dev_disp_s1.zero_raw))
257	        : absolute_mm;
258	    out->timestamp_us = (uint64_t)esp_timer_get_time();
259	    out->valid = true;
260	
261	    s_dev_disp_s1.is_online = true;
262	    return ESP_OK;
263	}
