63	    const TickType_t timeout_ticks = (timeout_ms == -1) ? portMAX_DELAY : pdMS_TO_TICKS(timeout_ms);
64	    return xSemaphoreTakeRecursive(lvgl_mux, timeout_ticks) == pdTRUE;
