72	static void lvgl_port_task(void *arg)
73	{
74	    ESP_LOGI(LVGL_TAG, "Starting LVGL task");
75	    uint32_t task_delay_ms = LVGL_TASK_MAX_DELAY_MS;
76	    while (1) {
77	        // Lock the mutex due to the LVGL APIs are not thread-safe
78	        if (lvgl_lock(-1)) {
79	
80	            ui_tick();
81	
82	            task_delay_ms = lv_timer_handler();
83	            // Release the mutex
84	            lvgl_unlock();
85	        }
86	        if (task_delay_ms > LVGL_TASK_MAX_DELAY_MS) {
87	            task_delay_ms = LVGL_TASK_MAX_DELAY_MS;
88	        } else if (task_delay_ms < LVGL_TASK_MIN_DELAY_MS) {
89	            task_delay_ms = LVGL_TASK_MIN_DELAY_MS;
90	        }
91	        vTaskDelay(pdMS_TO_TICKS(task_delay_ms));
92	    }
93	}
